package cn.binbin.crm;
import jakarta.validation.constraints.*;
import java.text.Normalizer;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import static cn.binbin.crm.TradeService.*;

@Service
public class FinanceService {
 public record ReceiptInput(@NotNull UUID contractId,@NotNull UUID planId,@NotNull @Min(1) @Max(100000000000L) Long amountCents,@NotNull LocalDate receivedDate,@NotBlank @Size(max=120) String paymentReference,@Size(max=120) String payerName,@Size(max=120) String bankName,@Size(max=2000) String notes,UUID proofAttachmentId,UUID correctionOfReceiptId,@Min(0) long expectedVersion,UUID fundAccountId){}
 public record DecisionInput(@Min(0) long expectedVersion,@Size(max=500) String reason,UUID proofAttachmentId){}
 public record ReverseInput(@Min(0) long expectedVersion,@NotNull @Min(1) @Max(100000000000L) Long amountCents,@NotNull LocalDate reversalDate,@NotBlank @Size(max=500) String reason,UUID proofAttachmentId){}
 private final TradeService trade;private final FinanceWorkspaceService funds;
 public FinanceService(TradeService trade,FinanceWorkspaceService funds){this.trade=trade;this.funds=funds;}
 public static String reference(String value){String s=Normalizer.normalize(value==null?"":value,Normalizer.Form.NFKC).toUpperCase(Locale.ROOT);if(s.codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT))throw ApiError.bad("到账凭证号包含无效字符");var b=new StringBuilder();s.codePoints().filter(c->!Character.isWhitespace(c)&&!Character.isSpaceChar(c)).forEach(b::appendCodePoint);if(b.isEmpty()||b.length()>120)throw ApiError.bad("请填写有效到账凭证号，最多120字");return b.toString();}
 private static void received(LocalDate d){date(d);if(d.isAfter(today()))throw ApiError.bad("到账 / 冲正日期不能晚于今天");}
 private static final String REVERSED="coalesce((SELECT sum(v.amount_cents) FROM crm_receipt_reversal v WHERE v.tenant_id=r.tenant_id AND v.receipt_id=r.id),0)";
 private static final String R_FROM=FROM+" JOIN crm_receipt r ON r.tenant_id=k.tenant_id AND r.contract_id=k.id JOIN sys_tenant_member creator ON creator.tenant_id=r.tenant_id AND creator.id=r.created_by_member_id ";
 private static final String EDIT="(:receiptWriter AND r.status='DRAFT' AND (creator.user_id=:actorUser OR :isManager))";
 private static final String CONFIRM="(:confirmer AND r.status='DRAFT' AND creator.user_id<>:actorUser AND k.status IN('SIGNED','ACTIVE','TERMINATED'))";
 private static final String R_SELECT="SELECT r.*,"+REVERSED+"::bigint AS reversed_cents,CASE WHEN r.status IN('CONFIRMED','REVERSED') THEN (r.amount_cents-"+REVERSED+")::bigint ELSE 0 END AS net_cents,("+EDIT+") AS can_write,("+CONFIRM+") AS can_confirm,(:reverser AND r.status='CONFIRMED' AND r.amount_cents>"+REVERSED+") AS can_reverse"+R_FROM;
 Map<String,Object> receipt(AuthService.Actor a,UUID id){if(!a.tradeAccess().receiptRead())throw ApiError.forbidden("没有回款读取权限");var p=trade.params(a);p.put("id",id);return trade.one(R_SELECT+"WHERE "+READ+" AND r.id=:id",p);}
 public Object receipt(AuthService.Session s,UUID id){return trade.scoped(s,"receipt",false,a->{var r=receipt(a,id);r.put("reversals",trade.rows("SELECT * FROM crm_receipt_reversal WHERE tenant_id=:tenant AND receipt_id=:id ORDER BY created_at,id",map("tenant",a.tenant().id(),"id",id)));return r;});}
 public Object receipts(AuthService.Session s,int page,int size,String q,String state,UUID contract,LocalDate from,LocalDate to){page(page,size,q);if(!Set.of("","DRAFT","CONFIRMED","REVERSED","VOID").contains(state))throw ApiError.bad("回款状态无效");if(from!=null)date(from);if(to!=null)date(to);if(from!=null&&to!=null&&to.isBefore(from))throw ApiError.bad("日期范围无效");return trade.scoped(s,"receipt",false,a->{if(contract!=null)trade.contract(a,contract);var p=trade.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"state",state,"contract",contract,"from",from,"to",to,"limit",size,"offset",((long)page-1)*size));String where=READ+" AND (:state='' OR r.status=:state) AND (cast(:contract AS uuid) IS NULL OR r.contract_id=:contract) AND (cast(:from AS date) IS NULL OR r.received_date>=:from) AND (cast(:to AS date) IS NULL OR r.received_date<=:to) AND (:q='' OR strpos(lower(r.receipt_number),:q)>0 OR strpos(lower(r.payment_reference),:q)>0 OR strpos(lower(r.customer_name_snapshot),:q)>0)";return new BusinessService.Page<>(trade.rows(R_SELECT+"WHERE "+where+" ORDER BY r.created_at DESC,r.id LIMIT :limit OFFSET :offset",p),page,size,trade.db.queryForObject("SELECT count(*)"+R_FROM+" WHERE "+where,p,Long.class));});}
 private Map<String,Object> validate(AuthService.Actor a,ReceiptInput input,UUID id){var k=trade.contract(a,input.contractId());if(!Set.of("SIGNED","ACTIVE","TERMINATED").contains(k.get("status")))throw ApiError.conflict("只有已签订合同可登记回款，作废草稿不能收款");received(input.receivedDate());reference(input.paymentReference());if(input.fundAccountId()!=null)funds.account(a,input.fundAccountId(),true);trade.one("SELECT id FROM crm_collection_plan WHERE tenant_id=:tenant AND contract_id=:contract AND id=:id AND active",map("tenant",a.tenant().id(),"contract",input.contractId(),"id",input.planId()));
  if(input.correctionOfReceiptId()!=null){var old=receipt(a,input.correctionOfReceiptId());if(!"REVERSED".equals(old.get("status"))||number(old,"netCents")!=0||!k.get("id").equals(old.get("contractId"))||!reference(input.paymentReference()).equals(old.get("referenceNorm")))throw ApiError.bad("更正登记需引用本合同同凭证号已全额冲正的原回款");}
  else if(trade.db.queryForObject("SELECT count(*) FROM crm_receipt WHERE tenant_id=:tenant AND reference_norm=:reference AND status='REVERSED'",map("tenant",a.tenant().id(),"reference",reference(input.paymentReference())),Integer.class)>0)throw ApiError.conflict("该凭证已有冲正历史，请引用原回款建立更正登记");
  trade.proof(a,k,id,input.correctionOfReceiptId(),input.proofAttachmentId());return k;
 }
 private Map<String,Object> input(AuthService.Actor a,UUID id,ReceiptInput i,Map<String,Object> k){var plan=trade.one("SELECT title FROM crm_collection_plan WHERE tenant_id=:tenant AND contract_id=:contract AND id=:plan AND active",map("tenant",a.tenant().id(),"contract",i.contractId(),"plan",i.planId()));return map("tenant",a.tenant().id(),"id",id,"contract",i.contractId(),"customer",k.get("customerId"),"plan",i.planId(),"amount",i.amountCents(),"date",i.receivedDate(),"reference",text(i.paymentReference()),"normalized",reference(i.paymentReference()),"payer",text(i.payerName()),"bank",text(i.bankName()),"notes",text(i.notes()),"planTitle",plan.get("title"),"contractNumber",k.get("contractNumber"),"customerName",k.get("customerNameSnapshot"),"proof",i.proofAttachmentId(),"correction",i.correctionOfReceiptId(),"member",a.tenant().memberId(),"name",a.tenant().memberName(),"version",i.expectedVersion(),"account",i.fundAccountId());}
 private String next(AuthService.Actor a,String kind){var p=map("tenant",a.tenant().id(),"year",today().getYear(),"kind",kind);long n=trade.db.queryForObject("INSERT INTO crm_receipt_counter(tenant_id,receipt_year,kind,next_value) VALUES(:tenant,:year,:kind,1) ON CONFLICT(tenant_id,receipt_year,kind) DO UPDATE SET next_value=crm_receipt_counter.next_value+1 RETURNING next_value",p,Long.class);return P4Numbering.format(trade.db,a.tenant().id(),kind.equals("RC")?"RECEIPT":"REVERSAL",today().getYear(),n,kind);}
 public Object create(AuthService.Session s,ReceiptInput i,String key,UUID trace){return trade.scoped(s,"receipt",true,a->{UUID id=trade.once(a,"receipt.create",key,i,()->{UUID created=UUID.randomUUID();var k=validate(a,i,null);var p=input(a,created,i,k);p.put("number",next(a,"RC"));trade.db.update("INSERT INTO crm_receipt(id,tenant_id,contract_id,customer_id,plan_id,receipt_number,amount_cents,received_date,payment_reference,reference_norm,payer_name,bank_name,notes,plan_title_snapshot,contract_number_snapshot,customer_name_snapshot,created_by_member_id,creator_name_snapshot,proof_attachment_id,correction_of_receipt_id,fund_account_id) VALUES(:id,:tenant,:contract,:customer,:plan,:number,:amount,:date,:reference,:normalized,:payer,:bank,:notes,:planTitle,:contractNumber,:customerName,:member,:name,:proof,:correction,:account)",p);trade.bindProof(a,i.contractId(),created,i.proofAttachmentId(),trace);revision(a,created,"CREATED","",trace);return created;});return receipt(a,id);});}
 public Object edit(AuthService.Session s,UUID id,ReceiptInput i,UUID trace){return trade.scoped(s,"receipt",true,a->{var old=receipt(a,id);if(!Boolean.TRUE.equals(old.get("canWrite")))throw ApiError.forbidden("仅登记人或获准经理可修改待确认回款");if(!old.get("contractId").equals(i.contractId())||!Objects.equals(old.get("correctionOfReceiptId"),i.correctionOfReceiptId()))throw ApiError.bad("已有登记不能更换合同或更正来源");var k=validate(a,i,id);int n=trade.db.update("UPDATE crm_receipt SET plan_id=:plan,amount_cents=:amount,received_date=:date,payment_reference=:reference,reference_norm=:normalized,payer_name=:payer,bank_name=:bank,notes=:notes,plan_title_snapshot=:planTitle,proof_attachment_id=:proof,fund_account_id=:account,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='DRAFT'",input(a,id,i,k));if(n!=1)throw ApiError.conflict("回款登记已变化，请刷新");trade.bindProof(a,i.contractId(),id,i.proofAttachmentId(),trace);revision(a,id,"UPDATED","",trace);return receipt(a,id);});}
 public Object confirm(AuthService.Session s,UUID id,DecisionInput i,String key,UUID trace){return trade.scoped(s,"confirm",true,a->{UUID selected=trade.once(a,"receipt.confirm",key,new Target(id,i),()->{var r=receipt(a,id);var k=trade.contract(a,(UUID)r.get("contractId"));if(!Boolean.TRUE.equals(r.get("canConfirm")))throw ApiError.forbidden("需由另一位指定权限经理核对待确认回款");if(number(r,"version")!=i.expectedVersion())throw ApiError.conflict("回款版本已变化，请刷新");UUID plan=(UUID)r.get("planId");var p=trade.one("SELECT * FROM crm_collection_plan WHERE tenant_id=:tenant AND contract_id=:contract AND id=:plan AND active",map("tenant",a.tenant().id(),"contract",k.get("id"),"plan",plan));long amount=number(r,"amountCents");
   if(amount>number(k,"totalCents")-trade.collected(a.tenant().id(),(UUID)k.get("id"))||amount>number(p,"amountCents")-trade.planCollected(a.tenant().id(),plan))throw new ApiError(org.springframework.http.HttpStatus.CONFLICT,"RECEIPT_BALANCE_EXCEEDED","回款超过合同或当前期次可收余额");UUID proof=i.proofAttachmentId()!=null?i.proofAttachmentId():(UUID)r.get("proofAttachmentId");trade.proof(a,k,id,(UUID)r.get("correctionOfReceiptId"),proof);int changed=trade.db.update("UPDATE crm_receipt SET status='CONFIRMED',confirmed_by_member_id=:member,confirmer_name_snapshot=:name,confirmed_at=now(),proof_attachment_id=:proof,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='DRAFT'",map("tenant",a.tenant().id(),"id",id,"member",a.tenant().memberId(),"name",a.tenant().memberName(),"proof",proof,"version",i.expectedVersion()));if(changed!=1)throw ApiError.conflict("回款版本已变化，请刷新");trade.bindProof(a,(UUID)k.get("id"),id,proof,trace);if(r.get("fundAccountId")!=null){funds.account(a,(UUID)r.get("fundAccountId"),true);funds.post(a,(UUID)r.get("fundAccountId"),"RECEIPT",id,amount,(LocalDate)r.get("receivedDate"),(String)r.get("paymentReference"),text(i.reason()));}revision(a,id,"CONFIRMED",text(i.reason()),trace);return id;});return receipt(a,selected);});}
 public Object cancel(AuthService.Session s,UUID id,DecisionInput i,String key,UUID trace){return trade.scoped(s,"receipt",true,a->{UUID selected=trade.once(a,"receipt.void",key,new Target(id,i),()->{var r=receipt(a,id);if(!Boolean.TRUE.equals(r.get("canWrite")))throw ApiError.forbidden("仅待确认回款可作废，已确认记录需冲正");if(text(i.reason()).isEmpty())throw ApiError.bad("请填写作废原因");int n=trade.db.update("UPDATE crm_receipt SET status='VOID',void_reason=:reason,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='DRAFT'",map("tenant",a.tenant().id(),"id",id,"version",i.expectedVersion(),"reason",text(i.reason())));if(n!=1)throw ApiError.conflict("回款已变化，请刷新");revision(a,id,"VOID",text(i.reason()),trace);return id;});return receipt(a,selected);});}
 public Object reverse(AuthService.Session s,UUID id,ReverseInput i,String key,UUID trace){return trade.scoped(s,"reverse",true,a->{UUID selected=trade.once(a,"receipt.reverse",key,new Target(id,i),()->{var r=receipt(a,id);var k=trade.contract(a,(UUID)r.get("contractId"));if(!Boolean.TRUE.equals(r.get("canReverse")))throw ApiError.forbidden("只有获准经理可冲正尚有净额的已确认回款");if(number(r,"version")!=i.expectedVersion())throw ApiError.conflict("回款版本已变化，请刷新");received(i.reversalDate());if(i.reversalDate().isBefore((LocalDate)r.get("receivedDate")))throw ApiError.bad("冲正日期不能早于原到账日期");String reason=text(i.reason());if(reason.isEmpty())throw ApiError.bad("请填写冲正原因");if(i.amountCents()>number(r,"netCents"))throw ApiError.conflict("冲正金额超过原回款尚可冲正金额");trade.proof(a,k,id,(UUID)r.get("correctionOfReceiptId"),i.proofAttachmentId());UUID reversal=UUID.randomUUID();trade.db.update("INSERT INTO crm_receipt_reversal(id,tenant_id,receipt_id,contract_id,plan_id,reversal_number,amount_cents,reversal_date,reason,actor_member_id,actor_name_snapshot,proof_attachment_id) VALUES(:reversal,:tenant,:receipt,:contract,:plan,:number,:amount,:date,:reason,:member,:name,:proof)",map("reversal",reversal,"tenant",a.tenant().id(),"receipt",id,"contract",r.get("contractId"),"plan",r.get("planId"),"number",next(a,"RV"),"amount",i.amountCents(),"date",i.reversalDate(),"reason",reason,"member",a.tenant().memberId(),"name",a.tenant().memberName(),"proof",i.proofAttachmentId()));int n=trade.db.update("UPDATE crm_receipt SET status=:state,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='CONFIRMED'",map("tenant",a.tenant().id(),"id",id,"version",i.expectedVersion(),"state",i.amountCents()==number(r,"netCents")?"REVERSED":"CONFIRMED"));if(n!=1)throw ApiError.conflict("回款已变化，请刷新");trade.bindProof(a,(UUID)k.get("id"),id,i.proofAttachmentId(),trace);if(r.get("fundAccountId")!=null)funds.post(a,(UUID)r.get("fundAccountId"),"RECEIPT_REVERSAL",reversal,-i.amountCents(),i.reversalDate(),(String)r.get("paymentReference"),reason);revision(a,id,"REVERSED",reason,trace);trade.audit(a,"RECEIPT_REVERSAL_CREATED","RECEIPT_REVERSAL",reversal,0,trace);return id;});return receipt(a,selected);});}
 private void revision(AuthService.Actor a,UUID id,String action,String reason,UUID trace){var r=receipt(a,id);r.keySet().removeAll(Set.of("canWrite","canConfirm","canReverse"));r.put("reversals",trade.rows("SELECT * FROM crm_receipt_reversal WHERE tenant_id=:tenant AND receipt_id=:id ORDER BY created_at,id",map("tenant",a.tenant().id(),"id",id)));trade.db.update("INSERT INTO crm_receipt_revision(id,tenant_id,receipt_id,business_version,action,snapshot,actor_member_id,actor_name_snapshot,reason) VALUES(:revision,:tenant,:receipt,:version,:action,cast(:snapshot AS jsonb),:member,:name,:reason)",map("revision",UUID.randomUUID(),"tenant",a.tenant().id(),"receipt",id,"version",r.get("version"),"action",action,"snapshot",trade.body(r),"member",a.tenant().memberId(),"name",a.tenant().memberName(),"reason",reason));trade.audit(a,"RECEIPT_"+action,"RECEIPT",id,number(r,"version"),trace);}
 public Object history(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return trade.scoped(s,"receipt",false,a->{receipt(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(trade.rows("SELECT id,business_version,action,reason,actor_name_snapshot,created_at FROM crm_receipt_revision WHERE tenant_id=:tenant AND receipt_id=:id ORDER BY business_version DESC LIMIT :limit OFFSET :offset",p),page,size,trade.db.queryForObject("SELECT count(*) FROM crm_receipt_revision WHERE tenant_id=:tenant AND receipt_id=:id",p,Long.class));});}
 public Object revision(AuthService.Session s,UUID id,long version){if(version<0)throw ApiError.bad("回款版本无效");return trade.scoped(s,"receipt",false,a->{receipt(a,id);return trade.object((String)trade.one("SELECT snapshot::text AS body FROM crm_receipt_revision WHERE tenant_id=:tenant AND receipt_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version)).get("body"));});}
 private static final String PERIOD_RECEIVED="coalesce((SELECT sum(r.amount_cents) FROM crm_receipt r WHERE r.tenant_id=k.tenant_id AND r.contract_id=k.id AND r.status IN('CONFIRMED','REVERSED') AND r.received_date BETWEEN :from AND :to),0)";
 private static final String PERIOD_REVERSED="coalesce((SELECT sum(v.amount_cents) FROM crm_receipt_reversal v WHERE v.tenant_id=k.tenant_id AND v.contract_id=k.id AND v.reversal_date BETWEEN :from AND :to),0)";
 private static final String OVERDUE="coalesce((SELECT sum(greatest(p.amount_cents-(coalesce((SELECT sum(r.amount_cents) FROM crm_receipt r WHERE r.tenant_id=p.tenant_id AND r.plan_id=p.id AND r.status IN('CONFIRMED','REVERSED')),0)-coalesce((SELECT sum(v.amount_cents) FROM crm_receipt_reversal v WHERE v.tenant_id=p.tenant_id AND v.plan_id=p.id),0)),0)) FROM crm_collection_plan p WHERE p.tenant_id=k.tenant_id AND p.contract_id=k.id AND p.active AND p.due_date<:today),0)";
 private Map<String,Object> reportParams(AuthService.Actor a,LocalDate from,LocalDate to,String q,String state,UUID customer){if(from==null)from=today().withDayOfMonth(1);if(to==null)to=today();date(from);date(to);if(to.isBefore(from)||to.isAfter(today())||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366||q.length()>100||!Set.of("","SIGNED","ACTIVE","TERMINATED").contains(state))throw ApiError.bad("对账条件无效，日期范围最多367天且不晚于今天");var p=trade.params(a);p.putAll(map("from",from,"to",to,"q",text(q).toLowerCase(Locale.ROOT),"state",state,"customer",customer));return p;}
 private static final String REPORT_WHERE=READ+" AND k.status IN('SIGNED','ACTIVE','TERMINATED') AND (:state='' OR k.status=:state) AND (cast(:customer AS uuid) IS NULL OR k.customer_id=:customer) AND (:q='' OR strpos(lower(k.title),:q)>0 OR strpos(lower(k.contract_number),:q)>0 OR strpos(lower(k.customer_name_snapshot),:q)>0)";
 private static final String REPORT="SELECT k.id,k.customer_id,k.contract_number,k.title,k.customer_name_snapshot,k.status,k.total_cents,"+CASH+"::bigint AS received_cents,(k.total_cents-"+CASH+")::bigint AS remaining_cents,"+PERIOD_RECEIVED+"::text AS period_received_cents,"+PERIOD_REVERSED+"::text AS period_reversed_cents,("+PERIOD_RECEIVED+"-"+PERIOD_REVERSED+")::text AS period_net_cents,"+OVERDUE+"::bigint AS overdue_cents"+FROM+" WHERE "+REPORT_WHERE;
 public Object reconciliation(AuthService.Session s,int page,int size,LocalDate from,LocalDate to,String q,String state,UUID customer){page(page,size,q);return trade.scoped(s,"reconcile",false,a->{var p=reportParams(a,from,to,q,state,customer);p.put("limit",size);p.put("offset",((long)page-1)*size);var summary=trade.one("SELECT count(*) AS contracts,coalesce(sum(total_cents),0)::text AS total_cents,coalesce(sum(received_cents),0)::text AS received_cents,coalesce(sum(remaining_cents),0)::text AS remaining_cents,coalesce(sum(overdue_cents),0)::text AS overdue_cents,coalesce(sum(period_received_cents::numeric),0)::text AS period_received_cents,coalesce(sum(period_reversed_cents::numeric),0)::text AS period_reversed_cents,coalesce(sum(period_net_cents::numeric),0)::text AS period_net_cents FROM ("+REPORT+") result",p);return map("items",trade.rows(REPORT+" ORDER BY k.contract_number LIMIT :limit OFFSET :offset",p),"summary",summary,"page",page,"pageSize",size,"total",summary.get("contracts"),"from",p.get("from"),"to",p.get("to"),"asOf",today());});}
 public byte[] export(AuthService.Session s,LocalDate from,LocalDate to,String q,String state,UUID customer,UUID trace){return trade.scoped(s,"cash-export",false,a->{var p=reportParams(a,from,to,q,state,customer);var rs=trade.rows(REPORT+" ORDER BY k.contract_number LIMIT 5001",p);if(rs.size()>5000)throw ApiError.bad("单次导出最多5000个合同，请缩小条件");var data=new ArrayList<List<Object>>();for(var r:rs)data.add(Arrays.asList(r.get("contractNumber"),r.get("title"),r.get("customerNameSnapshot"),r.get("status"),money(r.get("totalCents")),money(r.get("receivedCents")),money(r.get("remainingCents")),money(r.get("overdueCents")),money(r.get("periodReceivedCents")),money(r.get("periodReversedCents")),money(r.get("periodNetCents")),p.get("from"),p.get("to"),today()));trade.audit(a,"RECONCILIATION_EXPORTED","CONTRACT",a.tenant().id(),0,trace);return CsvSupport.write(List.of("合同编号","主题","客户","状态","合同金额（元）","当前净已收（元）","当前未收（元）","当前逾期（元）","期间到账（元）","期间冲正（元）","期间净额（元）","期间开始","期间结束","余额核对日期"),data);});}
}
